//! xcolor's sets of named colors, which its options `dvipsnames`, `svgnames` and `x11names` define
//! (as options of xcolor, of the document class or through `\PassOptionsToPackage`).
//!
//! The values are those xcolor's `\extractcolorspecs` gives for each color under pdflatex
//! (`texlive/texlive:TL2025-historic`): the dvipsnames are in cmyk, the others in rgb.

use super::Color;

/// A set of named colors.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Set {
    Dvips,
    Svg,
    X11,
}

impl Set {
    /// The set an xcolor option loads.
    pub fn of_option(option: &str) -> Option<Set> {
        match option.trim() {
            "dvipsnames" => Some(Set::Dvips),
            "svgnames" => Some(Set::Svg),
            "x11names" => Some(Set::X11),
            _ => None,
        }
    }

    /// The colors of the set, each with its name.
    pub fn colors(self) -> Vec<(&'static str, Color)> {
        match self {
            Set::Dvips => DVIPSNAMES.iter().map(|&(n, [c, m, y, k])| (n, Color::cmyk(c, m, y, k))).collect(),
            Set::Svg => SVGNAMES.iter().map(|&(n, [r, g, b])| (n, Color::rgb(r, g, b))).collect(),
            Set::X11 => X11NAMES.iter().map(|&(n, [r, g, b])| (n, Color::rgb(r, g, b))).collect(),
        }
    }

    pub fn color(self, name: &str) -> Option<Color> {
        match self {
            Set::Dvips => find(DVIPSNAMES, name).map(|[c, m, y, k]| Color::cmyk(c, m, y, k)),
            Set::Svg => find(SVGNAMES, name).map(|[r, g, b]| Color::rgb(r, g, b)),
            Set::X11 => find(X11NAMES, name).map(|[r, g, b]| Color::rgb(r, g, b)),
        }
    }
}

/// A color of any set, for a document that does not load the set: TeX stops there on an
/// undefined color, tikra draws it, the dvipsnames first (the svgnames have many of their names).
pub fn color(name: &str) -> Option<Color> {
    [Set::Dvips, Set::Svg, Set::X11].into_iter().find_map(|s| s.color(name))
}

fn find<const N: usize>(table: &[(&str, [f64; N])], name: &str) -> Option<[f64; N]> {
    table.binary_search_by(|(n, _)| n.cmp(&name)).ok().map(|i| table[i].1)
}

